#!/usr/bin/env python3
"""Differential test for `fate compile` against the oracle goldens.

The expected files under `golden/` are generated by the Java reference
(Script-Recompiler 0.7.11 @ 3433e6f), never hand-written, so a byte-identical match
is the acceptance criterion (ruling R1).

Three axes are compared per fixture, because the reference's behaviour is only
reproduced when all three agree:

  1. emitted assembly text - byte-exact against `<id>.expected`;
  2. emitted diagnostics - stderr against the message lines of `<id>.diag`;
  3. exit status - against the native 0/1/2/3 contract for the fixture's `expect`.

Axis 2 was checked by hand until 2026-10-28, which is how four silently-wrong runs
stayed green (a missing `3: ` line prefix, two missing tab warnings, a missing
`unknown function`, and one line the reference never prints).

How the diagnostic comparison works, and why it looks the way it does:

  * The `.diag` files hold what the oracle recorded: `exit=`, `produced_output=`, then
    one message per line. The capture kept `sorted(set(lines))`, so the artifact has no
    emission order and no duplicates. The comparison is therefore ORDER-INSENSITIVE by
    construction (both sides sorted) but MULTISET-STRICT: every line the tool printed
    must appear in the golden with the same multiplicity, so a missing message, an
    extra one, or a wrong line-number prefix fails. It cannot see a message the
    reference emitted twice and the capture collapsed; that is a limit of the artifact,
    not a choice made here.

  * The reference's own crash output (`Failed to compile:` and the `java.*` trace) is
    NOT reproduced - ruling R1 calls it a defect. Those lines are dropped from the
    expectation. This is the only blanket filter, it is exact-match on the banner plus
    a prefix test on Java stack/artefact lines, and it is reported when it fires.

  * Where a fixture's expectation is not what the tool prints for a documented reason,
    the divergence is written out in `manifest.json` as `diag_expect` (an explicit
    expected list) or `"diag": "unpinned"` (not compared, reported as NOT VERIFIED).
    A fixture is never allowed to pass by saying nothing.

Two kinds of byte-parity entry, set by `parity` in manifest.json:

  `match`     (default) byte-exact agreement with the golden is required.
  `deviation` accepted divergence from the reference, for input that is not valid Fate
              and where the reference's output is a by-product of ANTLR's error
              recovery. The run must still fail with a diagnosed exit 3, must not
              crash, and must not silently start matching again.

`expect` drives the exit-status check: `clean` and `silent-wrong` want exit 0,
`warnings` wants exit 0 with stderr (the tab class: printed, but not errors-list
entries), `diagnostics` and `crash` want exit 3. `exit` overrides it verbatim.

The metadata bundle is NOT committed. It is read from `$FATE_META_DIR` when set, and
otherwise from a small list of local locations. If the goldens, the binary or the
bundle are missing, the test skips loudly with exit 77 (CTest NOT_APPLICABLE) rather
than reporting a vacuous pass.

Usage: run_golden.py <path-to-fate> <testdata-dir>
"""

from __future__ import annotations

import hashlib
import json
import os
import pathlib
import subprocess
import sys
import tempfile

SKIP = 77

# Exit status each `expect` class must answer with. `warnings` is 0 because the
# reference's tokenizer complaints never reach its errors list, and the native
# contract keys exit 3 off that list.
EXPECT_EXIT = {
    "clean": 0,
    "silent-wrong": 0,
    "warnings": 0,
    "diagnostics": 3,
    "crash": 3,
}

CRASH_BANNER = "Failed to compile:"


def fingerprint(paths: list[pathlib.Path]) -> dict[pathlib.Path, str]:
    """sha256 of each file, for the read-only input check in `main`."""
    return {p: hashlib.sha256(p.read_bytes()).hexdigest() for p in paths if p.is_file()}


def find_meta() -> pathlib.Path | None:
    """Return a metadata directory holding params.csv, or None.

    The whole function runs on any interpreter the runner happens to have, so the
    annotation above is only a hint (`from __future__ import annotations`); without
    it, a host whose default `python3` predates 3.10 raised TypeError here instead
    of reaching the skip path.
    """
    candidates = []

    env = os.environ.get("FATE_META_DIR")

    if env:
        candidates.append(pathlib.Path(env))

    # Default local bundle: the reference checkout's own metadata, if present.
    for base in (pathlib.Path.home() / "Documents/GitHub", pathlib.Path.home()):
        candidates.append(base / "Severed-Chains/patches/meta")

    for c in candidates:
        if (c / "params.csv").is_file():
            return c

    return None


def is_crash_artifact(line: str) -> bool:
    """True for the reference's own crash output, which is not reproduced (R1).

    Narrow on purpose: the banner plus Java exception and stack lines. A real
    diagnostic that happened to start with one of these prefixes would be hidden, so
    the caller reports the filter whenever it fires instead of applying it quietly.
    """
    return (line == CRASH_BANNER or line.startswith("java.") or line.startswith("at ")
            or line.startswith("Caused by:"))


def read_diag(path: pathlib.Path) -> list[str]:
    """Return the message lines of a `.diag` capture.

    The `exit=` and `produced_output=` headers describe the reference, which exits 0
    even when it logs errors. The native exit contract is checked against the manifest
    instead, so the header lines are skipped rather than compared.
    """
    if not path.is_file():
        return []

    messages = []

    for raw in path.read_text().splitlines():
        line = raw.strip()

        if not line or line.startswith("exit=") or line.startswith("produced_output="):
            continue

        messages.append(line)

    return messages


def check_diagnostics(entry: dict, golden: pathlib.Path, fid: str,
                      stderr_text: str) -> tuple[str, list[str]]:
    """Compare the run's stderr with the fixture's expectation.

    Returns (state, failures) where state is `ok`, `override`, `filtered` or
    `unpinned`. `unpinned` produces a note, not a failure: that fixture's divergence is
    a documented parse-recovery by-product, and the point of naming it is that the
    harness says so out loud rather than passing in silence.
    """
    if entry.get("diag") == "unpinned":
        return "unpinned", []

    override = entry.get("diag_expect")
    messages = read_diag(golden / f"{fid}.diag")

    if override is not None:
        want = list(override)
        state = "override"
    else:
        kept = [m for m in messages if not is_crash_artifact(m)]
        dropped = [m for m in messages if is_crash_artifact(m)]
        want = kept
        state = "filtered" if dropped else "ok"

    got = [line.strip() for line in stderr_text.splitlines() if line.strip()]

    # Order-insensitive because the golden was captured sorted; multiset-strict so a
    # dropped or duplicated message still fails.
    if sorted(got) == sorted(want):
        return state, []

    failures = [f"{fid}: diagnostics differ from the oracle"]
    failures.append(f"    expected: {' | '.join(want) if want else '(none)'}")
    failures.append(f"    actual  : {' | '.join(got) if got else '(none)'}")
    return state, failures


def main(argv: list[str]) -> int:
    if len(argv) < 3:
        print(f"usage: {sys.argv[0]} <fate-binary> <testdata-dir>")
        return 2

    binary = pathlib.Path(argv[1])
    testdata = pathlib.Path(argv[2])

    if not binary.is_file():
        print(f"SKIP: no fate binary at {binary}")
        return SKIP

    manifest = testdata / "manifest.json"
    golden = testdata / "golden"
    fixtures = testdata / "fixtures"

    if not manifest.is_file() or not golden.is_dir():
        print("SKIP: golden corpus not available to this checkout")
        return SKIP

    meta = find_meta()

    if meta is None:
        print("SKIP: no metadata bundle (set FATE_META_DIR or provide "
              "Severed-Chains/patches/meta)")
        return SKIP

    entries = json.loads(manifest.read_text())["fixtures"]

    # The fixture set is an input, not scratch space. Two incidents so far were probes
    # that redirected output onto a fixture path and truncated it, and the suite stayed
    # green afterwards because a 1-byte file still compiles. Snapshot every input and
    # re-check at the end so that class of accident fails loudly instead of quietly
    # redefining what "green" means.
    inputs = fingerprint(sorted((fixtures).glob("*.fate"))
                         + sorted((golden).glob("*.expected"))
                         + sorted((golden).glob("*.diag")))

    failures: list[str] = []
    notes: list[str] = []
    deviations = 0
    unchecked = 0

    for entry in entries:
        fid = entry["id"]
        src = fixtures / f"{fid}.fate"
        want = golden / f"{fid}.expected"

        if not src.is_file() or not want.is_file():
            failures.append(f"{fid}: missing fixture or golden")
            continue

        with tempfile.TemporaryDirectory() as tmp:
            out = pathlib.Path(tmp) / "out.txt"
            cmd = [str(binary), "compile", "-m", str(meta), *entry.get("args", []),
                   "-o", str(out), str(src)]
            cmd = [a.replace("$FIXTURES", str(fixtures)) for a in cmd]

            try:
                proc = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            except subprocess.TimeoutExpired:
                failures.append(f"{fid}: timed out after 30s")
                continue

            # --- axis 1: emitted assembly text -----------------------------------
            if entry.get("parity") == "deviation":
                # Pinned as an accepted deviation: the bytes are not expected to match,
                # but the properties below still have to hold. A crash (negative return
                # code) or a silent success is a regression. So is a byte-exact match,
                # which would mean the pin is no longer needed and should be retired
                # rather than left to rot.
                if proc.returncode < 0:
                    failures.append(f"{fid}: crashed with signal {-proc.returncode}")
                    continue
                if proc.returncode != 3:
                    failures.append(f"{fid}: deviation pin expects a diagnosed failure "
                                    f"(exit 3), got exit {proc.returncode}")
                    continue
                if out.is_file() and out.read_bytes() == want.read_bytes():
                    failures.append(f"{fid}: now matches the golden, so the deviation "
                                    "pin is obsolete - set parity back to 'match'")
                    continue
                deviations += 1
            else:
                expected_writes = want.stat().st_size > 0

                if expected_writes and not out.is_file():
                    failures.append(f"{fid}: wrote no output, golden has "
                                    f"{want.stat().st_size} bytes (rc={proc.returncode})")
                    continue

                if not expected_writes and out.is_file() and out.stat().st_size > 0:
                    failures.append(f"{fid}: expected no output, got {out.stat().st_size} "
                                    f"bytes (rc={proc.returncode})")
                    continue

                got = out.read_bytes() if out.is_file() else b""

                if got != want.read_bytes():
                    want_bytes = want.read_bytes()
                    first = next((i for i in range(min(len(got), len(want_bytes)))
                                  if got[i] != want_bytes[i]), min(len(got), len(want_bytes)))
                    failures.append(f"{fid}: differs at byte {first} "
                                    f"(rc={proc.returncode}, {len(got)} vs {len(want_bytes)} bytes)")

            # --- axis 2: diagnostics ------------------------------------------------
            state, diag_failures = check_diagnostics(entry, golden, fid, proc.stderr)

            if state in ("unpinned", "filtered"):
                unchecked += 1
                notes.append(f"NOT VERIFIED {fid}: "
                             + ("diagnostics are not compared for this fixture"
                                if state == "unpinned"
                                else f"reference crash lines dropped from the expectation"))

            if diag_failures:
                failures.extend(diag_failures)
                continue

            # --- axis 3: exit status ------------------------------------------------
            want_exit = entry.get("exit")

            if want_exit is None:
                expect = entry.get("expect", "clean")
                want_exit = EXPECT_EXIT.get(expect)

                if want_exit is None:
                    failures.append(f"{fid}: manifest 'expect' is not a known class: {expect}")
                    continue

            if proc.returncode != want_exit:
                failures.append(f"{fid}: exit {proc.returncode}, manifest expects "
                                f"{want_exit} (expect={entry.get('expect')})")

    mutated = [str(p.relative_to(testdata)) for p, digest in inputs.items()
               if fingerprint([p])[p] != digest]

    if mutated:
        failures.append("fixtures/goldens changed during the run - these are read-only "
                        "inputs, a probe has written over them: " + ", ".join(mutated))

    for f in failures:
        print(f"FAIL {f}")

    for n in notes:
        print(n)

    if failures:
        print(f"\n{len(failures)} check(s) did not match the oracle "
              f"({len(entries)} fixture(s))")
        return 1

    strict = len(entries) - deviations
    tail = f", {deviations} pinned deviation(s)" if deviations else ""

    if unchecked:
        print(f"({unchecked} fixture(s) ran with diagnostics NOT VERIFIED - see above)")

    print(f"fate compile: {strict}/{len(entries)} match the oracle goldens{tail}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
